import{_ as t,o,c as a,a2 as n}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Cloud Governance — enumerated source for the Cloud Governance assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/cloud-governance-question-set.md","filePath":"frameworks/cloud-governance-question-set.md"}'),r={name:"frameworks/cloud-governance-question-set.md"};function i(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="cloud-governance-—-enumerated-source-for-the-cloud-governance-assessment" tabindex="-1">Cloud Governance — enumerated source for the Cloud Governance assessment <a class="header-anchor" href="#cloud-governance-—-enumerated-source-for-the-cloud-governance-assessment" aria-label="Permalink to &quot;Cloud Governance — enumerated source for the Cloud Governance assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p><strong>Framework version:</strong> Not versioned by Microsoft — the Cloud Governance assessment and the CAF Govern documentation it is built from carry no release number. The extraction date above (2026-08-01) is the version, per <code>docs/frameworks/README.md</code>; re-date this line when this file is next re-verified.</p><p>This is the AB#6811 enumeration for target #8 in the audit&#39;s fourteen-assessment programme (<code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §14): <em>&quot;Cloud Governance — policy data already collected … Policy compliance state is collected and scored by nothing.&quot;</em> The audit&#39;s §8 Table 3 identifies this as the <strong>CAF Govern methodology</strong> — a different axis from the &quot;Governance&quot; <em>design area</em> that <code>caf.governance.yaml</code> already scores (that design area is part of Ready, covered in <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §8 Table 2, not this document). Per DQ12, no <code>caf.govern.yaml</code> (or similarly named methodology file) is written until this enumeration exists.</p><h2 id="what-cloud-governance-is" tabindex="-1">What Cloud Governance is <a class="header-anchor" href="#what-cloud-governance-is" aria-label="Permalink to &quot;What Cloud Governance is&quot;">​</a></h2><p>Microsoft ships <strong>two</strong> distinct things under &quot;governance,&quot; and this file is about the second one:</p><ol><li><code>caf.governance.yaml</code>&#39;s subject — the Ready methodology&#39;s <strong>Governance design area</strong>, one of the 8 landing-zone design areas, already enumerated and scored (10 recommendations, ~70% coverage per the audit).</li><li><strong>This file&#39;s subject</strong> — the <strong>Govern methodology</strong>, one of CAF&#39;s seven core methodologies (Strategy, Plan, Ready, Adopt, Govern, Secure, Manage — confirmed in <code>smart-question-set.md</code>&#39;s sibling audit table). Govern is a <strong>five-step continuous process</strong> — build a governance team, assess cloud risks, document policies, enforce policies, monitor compliance — applied across <strong>seven risk categories</strong>: regulatory compliance, security, cost, operations, data, resource management, AI.</li></ol><p>There is also an interactive <strong>&quot;Cloud Governance&quot;</strong> assessment on the Microsoft Assessments platform (<a href="https://learn.microsoft.com/en-us/assessments/b1891add-7646-4d60-a875-32a4ab26327e/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/b1891add-7646-4d60-a875-32a4ab26327e/</a>), which is almost certainly built on the Govern methodology&#39;s five steps and seven categories, but — as with SMART, the AVS assessment, and CASA — its question text and numbers are not published. This enumeration draws on the fully-published CAF Govern documentation instead.</p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-08-01):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>The Cloud Governance assessment landing page</td><td>Confirms the assessment exists. <strong>No question text.</strong></td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/overview" target="_blank" rel="noreferrer">What is the Microsoft Cloud Adoption Framework?</a></td><td>The seven-methodology structure and Govern&#39;s place in it</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/govern/assess-cloud-risks" target="_blank" rel="noreferrer">Assess cloud risks</a></td><td>The seven risk categories (RC/SC/CM/OP/DG/RM/AI), already verified in the audit&#39;s §8 Table 3</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/govern/document-cloud-governance-policies" target="_blank" rel="noreferrer">Document cloud governance policies</a></td><td>The policy-documentation structure (ID, category, risk ID, statement, scope, remediation, monitoring tool) and a worked example table naming a monitoring tool per category</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/govern/monitor-cloud-governance" target="_blank" rel="noreferrer">Monitor cloud compliance</a></td><td>Per-category &quot;Azure facilitation&quot; recommendations — the concrete, tool-named observable signals this enumeration is built from</td></tr></tbody></table><p><strong>⚠️ The interactive assessment&#39;s question TEXT and NUMBERS are not published.</strong> The <code>CGOV-*</code> identifiers below are <strong>Scout&#39;s own</strong>, built from the CAF Govern documentation&#39;s per-category Azure-facilitation guidance, not Microsoft&#39;s question numbers.</p><p><strong>Shelf life.</strong> CAF Govern is actively maintained content; re-verify before quoting.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><h3 id="rc-—-regulatory-compliance" tabindex="-1">RC — Regulatory compliance <a class="header-anchor" href="#rc-—-regulatory-compliance" aria-label="Permalink to &quot;RC — Regulatory compliance&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-RC-01</td><td>Policy compliance dashboards are used to get compliance data on assigned policies</td><td>✅ <code>Management/PolicyComplianceStates</code></td></tr><tr><td>CGOV-RC-02</td><td>Causes of noncompliance are determined and root-caused, not just observed</td><td>❌ Compliance state is collected; no root-cause field</td></tr></tbody></table><h3 id="sc-—-security" tabindex="-1">SC — Security <a class="header-anchor" href="#sc-—-security" aria-label="Permalink to &quot;SC — Security&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-SC-01</td><td>Security recommendations are reviewed and secure score is monitored over time</td><td>⚠️ Partial — <code>Security/DefenderSecureScore</code>, <code>Security/DefenderAssessments</code> are point-in-time, not a trend</td></tr><tr><td>CGOV-SC-02</td><td>A regulatory-compliance dashboard is checked against common security frameworks (MCSB, CIS, etc.)</td><td>⚠️ Partial — <code>Management/PolicyComplianceStates</code> carries the data; nothing distinguishes which framework initiative each state belongs to (same gap the audit&#39;s §8 Table 4 documents)</td></tr><tr><td>CGOV-SC-03</td><td>Identity governance monitoring is configured — audit/sign-in/provisioning logs, identity secure score, an identity-governance dashboard</td><td>❌ Sign-in/audit logs not collected; <code>Identity/PIMAssignments</code> gives a partial standing-vs-eligible signal only</td></tr></tbody></table><h3 id="cm-—-cost-management" tabindex="-1">CM — Cost management <a class="header-anchor" href="#cm-—-cost-management" aria-label="Permalink to &quot;CM — Cost management&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-CM-01</td><td>Cost analysis gives full visibility into cloud costs</td><td>⚠️ Partial — <code>General/Reservations</code>, <code>Management/AdvisorScore</code> give partial visibility; no full cost-analysis dataset</td></tr><tr><td>CGOV-CM-02</td><td>Budgets are created that align with the desired cloud investment</td><td>✅ <code>Management/Budgets</code></td></tr><tr><td>CGOV-CM-03</td><td>Cost-optimization recommendations are used to detect idle resources</td><td>✅ <code>$.advisor[?(@.Category == &#39;Cost&#39;)]</code>, <code>$.costCleanup.orphanedDisks</code>, <code>$.costCleanup.orphanedPips</code></td></tr><tr><td>CGOV-CM-04</td><td>Cost anomalies and unexpected changes are identified</td><td>⚠️ Partial — <code>src/analyze/Get-ScoutCostAnomaly.ps1</code> implements spike/z-score/IQR detection against <code>src/collect/Get-ScoutCostInventory.ps1</code> output, but nothing in <code>Invoke-Collect.ps1</code> calls it; the function exists and is unused, not absent</td></tr></tbody></table><h3 id="op-—-operations" tabindex="-1">OP — Operations <a class="header-anchor" href="#op-—-operations" aria-label="Permalink to &quot;OP — Operations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-OP-01</td><td>Policy compliance is tracked for operations-scoped governance policies</td><td>✅ <code>Management/PolicyComplianceStates</code> (generic — not operations-specific)</td></tr><tr><td>CGOV-OP-02</td><td>Logs and metrics are monitored for availability and performance</td><td>⚠️ Partial — <code>Monitor/Workspaces</code>, <code>Monitor/DataCollectionRules</code> existence only, not coverage or content</td></tr><tr><td>CGOV-OP-03</td><td>Advisor is used to monitor reliability/security/performance/cost, with alerts set on new recommendations</td><td>⚠️ Partial — <code>$.advisor[*]</code> gives the recommendations; whether alerts are configured on <em>new</em> ones is not observable</td></tr><tr><td>CGOV-OP-04</td><td>Resource health is monitored for service-impacting events and planned maintenance</td><td>❌ <code>Monitor/Outages</code> exists but the audit&#39;s build-list item A5 records it as currently broken (runs before the data it reads is merged)</td></tr></tbody></table><h3 id="dg-—-data" tabindex="-1">DG — Data <a class="header-anchor" href="#dg-—-data" aria-label="Permalink to &quot;DG — Data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-DG-01</td><td>Data compliance, management, and usage are monitored (Microsoft Purview)</td><td>❌ Purview is not collected by Scout</td></tr><tr><td>CGOV-DG-02</td><td>Dashboards monitor compliance with data-plane policies</td><td>❌ Data-plane policy state is not collected</td></tr></tbody></table><h3 id="rm-—-resource-management" tabindex="-1">RM — Resource management <a class="header-anchor" href="#rm-—-resource-management" aria-label="Permalink to &quot;RM — Resource management&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-RM-01</td><td>Policies on resource deployments — e.g. tag-enforcement policies — are monitored for compliance</td><td>✅ <code>Management/PolicyComplianceStates</code>, <code>$.tags[*]</code></td></tr></tbody></table><h3 id="ai-—-artificial-intelligence" tabindex="-1">AI — Artificial intelligence <a class="header-anchor" href="#ai-—-artificial-intelligence" aria-label="Permalink to &quot;AI — Artificial intelligence&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-AI-01</td><td>AI system outputs are monitored — abuse monitoring and content filtering configured</td><td>❌ Not collected — no AI Foundry/content-filter configuration ingest</td></tr><tr><td>CGOV-AI-02</td><td>Customer-facing AI systems are red-teamed on a recurring cadence</td><td>❌ Organisational/process; no Azure artefact records a red-team cadence</td></tr></tbody></table><h3 id="proc-—-the-governance-process-itself-steps-1–3-of-the-five-step-cycle" tabindex="-1">PROC — The governance process itself (steps 1–3 of the five-step cycle) <a class="header-anchor" href="#proc-—-the-governance-process-itself-steps-1–3-of-the-five-step-cycle" aria-label="Permalink to &quot;PROC — The governance process itself (steps 1–3 of the five-step cycle)&quot;">​</a></h3><p>These sit before the two steps (enforce, monitor) that the categories above already draw on. All five are organisational — Scout reads the <em>result</em> of governance being enforced, never the process that produced the policy.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>CGOV-PROC-01</td><td>A cloud governance team is formally established with a charter and defined membership</td><td>❌ Organisational</td></tr><tr><td>CGOV-PROC-02</td><td>Governance policies are documented in a standard format (policy ID, category, risk ID, statement, scope, remediation, monitoring tool)</td><td>❌ Organisational — <code>Management/PolicyDefinitions</code>/<code>PolicyAssignments</code> carry display name and description, but not whether they follow this authoring standard</td></tr><tr><td>CGOV-PROC-03</td><td>Policies are distributed via a centralized repository, with compliance checklists for teams</td><td>❌ Organisational</td></tr><tr><td>CGOV-PROC-04</td><td>A compliance baseline was established and is tracked against over time</td><td>❌ Scout collects a single point-in-time snapshot per run; no historical baseline is retained between runs</td></tr><tr><td>CGOV-PROC-05</td><td>Noncompliance remediation has a defined timeline and escalation path scaled to risk severity</td><td>❌ Organisational</td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p><strong>9 of 23 items are fully or partially answerable from data Scout already collects; 14 are organisational, unobservable, or blocked by a known defect.</strong> The single biggest lever here is the same one the audit&#39;s §10 flags for the whole document: <strong><code>Management/PolicyComplianceStates</code> is collected and read by nothing.</strong> Four of the nine answerable items (<code>CGOV-RC-01</code>, <code>CGOV-SC-02</code>, <code>CGOV-OP-01</code>, <code>CGOV-RM-01</code>) all resolve to that single dataset. Writing the render/scoring layer for policy compliance state — already flagged as the cheapest high-value work in §8 Table 4 — closes nearly half of what this assessment can ever automate. The <code>CGOV-DG-*</code> and <code>CGOV-AI-*</code> categories are close to a hard floor: Purview and AI Foundry content-filter configuration are simply not in Scout&#39;s collection scope today, and closing them means adding new collectors, not new rules.</p>',33)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
